const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});try{const p=await b.newPage();await p.goto('http://127.0.0.1:4183/');console.log(await p.evaluate(async()=>{requestAnimationFrame=()=>0;const es=await Promise.all((await TenzerConfig.load('config.json')).entries.filter(e=>['flower','waterfall','moon','lightning','water'].includes(e.id)).map(TenzerScenes.prepare)),out=[];for(const entry of es){const c=document.createElement('canvas');c.width=2400;c.height=1500;const g=c.getContext('2d');g.scale(2,2);const s={entry,life:8,x:600,y:350};drawStockScene(g,s,1,1200,750,false);const start=performance.now();for(let i=0;i<20;i++){s.life=8+i/60;g.clearRect(0,0,1200,750);drawStockScene(g,s,1,1200,750,false);g.getImageData(0,0,1,1)}out.push({scene:entry.id,ms:((performance.now()-start)/20).toFixed(1)})}return out}));}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
